"""Rollback-only authorization harness on the dedicated local Docker database.
The membership helper is a controlled model here; native tests exercise the live helper.
"""
from pathlib import Path
import subprocess
ROOT = Path(__file__).resolve().parents[1]
SETUP = 'begin;\ncreate schema assignment_guard_test;\ncreate table assignment_guard_test.assignments(id uuid primary key,team_id uuid,author_id uuid,created_by uuid,title text,description text,link text,due_text text,attachments jsonb,status text,published_at timestamptz);\ncreate table assignment_guard_test.team_members(team_id uuid,user_id uuid,role text);\ncreate table assignment_guard_test.assignment_done(assignment_id uuid,user_id uuid,primary key(assignment_id,user_id));\ncreate table assignment_guard_test.assignment_test_teams(id uuid,archived boolean default false);\ncreate function assignment_guard_test.is_active_team_member(p_team_id uuid) returns boolean language sql as $$select exists(select 1 from assignment_guard_test.team_members m join assignment_guard_test.assignment_test_teams t on t.id=m.team_id where m.team_id=p_team_id and m.user_id=auth.uid() and not t.archived)$$;\n-- Guard legacy SECURITY DEFINER mutations without changing the client contract.\n'
CHECKS = "do $$\ndeclare a uuid:=gen_random_uuid();o uuid:=gen_random_uuid();m uuid:=gen_random_uuid();x uuid:=gen_random_uuid();t uuid:=gen_random_uuid();r uuid:=gen_random_uuid();\nbegin\ninsert into assignment_guard_test.assignment_test_teams values(t,false);\ninsert into assignment_guard_test.team_members values(t,a,'member'),(t,o,'owner'),(t,m,'member');\ninsert into assignment_guard_test.assignments(id,team_id,author_id,title,status) values(r,t,a,'before','published');\nperform set_config('request.jwt.claim.sub',x::text,true);\nbegin perform assignment_guard_test.remove_assignment(r);raise exception 'outsider delete accepted';exception when insufficient_privilege then null;end;\nbegin perform assignment_guard_test.update_assignment(r,'bad','','','','[]');raise exception 'outsider edit accepted';exception when insufficient_privilege then null;end;\nbegin perform assignment_guard_test.set_assignment_done(r,true);raise exception 'outsider done accepted';exception when insufficient_privilege then null;end;\nif not exists(select 1 from assignment_guard_test.assignments where id=r and title='before') then raise exception 'denial mutated row';end if;\nperform set_config('request.jwt.claim.sub',m::text,true);\nbegin perform assignment_guard_test.remove_assignment(r);raise exception 'member delete accepted';exception when insufficient_privilege then null;end;\nbegin perform assignment_guard_test.update_assignment(r,'bad','','','','[]');raise exception 'member edit accepted';exception when insufficient_privilege then null;end;\nperform assignment_guard_test.set_assignment_done(r,true);perform assignment_guard_test.set_assignment_done(r,false);\nperform set_config('request.jwt.claim.sub',a::text,true);perform assignment_guard_test.update_assignment(r,'author edited','','','','[]');\ndelete from assignment_guard_test.team_members where user_id=a;\nbegin perform assignment_guard_test.remove_assignment(r);raise exception 'removed author accepted';exception when insufficient_privilege then null;end;\nperform set_config('request.jwt.claim.sub',o::text,true);update assignment_guard_test.assignment_test_teams set archived=true;\nbegin perform assignment_guard_test.remove_assignment(r);raise exception 'archived owner accepted';exception when insufficient_privilege then null;end;\nupdate assignment_guard_test.assignment_test_teams set archived=false;perform assignment_guard_test.remove_assignment(r);\nif exists(select 1 from assignment_guard_test.assignments where id=r) then raise exception 'owner delete failed';end if;\nif has_function_privilege('anon','assignment_guard_test.remove_assignment(uuid)','execute') then raise exception 'anon grant';end if;\nraise notice 'PASS authorization branches, denied writes unchanged, local transaction rolled back';\nend $$;\nrollback;\n"
sql = (ROOT/'supabase/migrations/20261030003733_assignment_mutation_authorization.sql').read_text(encoding='utf-8')
sql = sql.replace('public.', 'assignment_guard_test.').replace('private.is_active_team_member', 'assignment_guard_test.is_active_team_member')
result = subprocess.run(['docker', 'exec', '-i', 'supabase_db_student_platform_e2e', 'psql', '-U', 'postgres', '-d', 'postgres', '-v', 'ON_ERROR_STOP=1'], input=(SETUP+sql+CHECKS).encode(), capture_output=True)
print(result.stdout.decode())
print(result.stderr.decode())
raise SystemExit(result.returncode)
